import {t} from './locales.js';
import {iso as projectIso,diamond} from './isometric.js';
import {bindCamera,cameraRotation} from './camera.js';
/** @param {number} x @param {number} y */
const iso=(x,y)=>projectIso(x,y,cameraRotation('cow'));
const NS='http://www.w3.org/2000/svg';
/** @param {string} name @param {Record<string,string|number>} attrs @param {Element} parent */
function node(name,attrs,parent){const n=document.createElementNS(NS,name);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,String(v));parent.append(n);return n;}
/** @param {{x:number,y:number}[]} values */
const points=values=>values.map(p=>p.x+','+p.y).join(' ');
/** @param {number} x @param {number} y @param {number} w @param {number} h */
const corners=(x,y,w,h)=>[iso(x,y),iso(x+w,y),iso(x+w,y+h),iso(x,y+h)];
/** @param {{x:number,y:number}} p @param {number} h */
const up=(p,h)=>({x:p.x,y:p.y-h});
/** @param {Element} parent @param {number[]} edge */
function fence(parent,edge){const a=iso(edge[0],edge[1]),b=iso(edge[2],edge[3]),g=node('g',{'data-cow-fence':'','pointer-events':'none'},parent);for(const h of [12,25])node('path',{d:`M${a.x},${a.y-h} L${b.x},${b.y-h}`,stroke:'#b69b6b','stroke-width':3},g);for(let i=0;i<=5;i++){const x=a.x+(b.x-a.x)*i/5,y=a.y+(b.y-a.y)*i/5;node('path',{d:`M${x},${y+3} v-37`,stroke:'#bcaa7a','stroke-width':5,'stroke-linecap':'round'},g);}}
/** Cutaway shelter keeps the straw rest space visible. @param {Element} parent @param {ReturnType<typeof import('./cow-scene-snapshot.js').cowSnapshot>} snapshot */
function barn(parent,snapshot){const [a,b,c,d]=corners(1,.7,3.2,2.1),g=node('g',{'data-cow-barn':'','data-cow-object':'barn','aria-label':t('cowBarnShelter')},parent);node('polygon',{points:points([a,b,c,d]),fill:'#ddca93',stroke:'#b6a26c','stroke-width':2},g);node('polygon',{points:points([a,b,up(b,55),up(a,55)]),fill:'#caa883',stroke:'#ab8862','stroke-width':2},g);node('polygon',{points:points([a,d,up(d,55),up(a,55)]),fill:'#dfc29a',stroke:'#ab8862','stroke-width':2},g);const roof=corners(.8,.5,3.6,1.1).map(p=>up(p,66)),ridge=corners(.8,.5,3.6,.05).map(p=>up(p,85));node('polygon',{points:points([roof[3],roof[2],ridge[1],ridge[0]]),fill:'#b77455',stroke:'#985d43','stroke-width':2},g);node('polygon',{points:points([roof[0],roof[1],ridge[1],ridge[0]]),fill:'#cb8b65'},g);for(const p of [b,c,d])node('path',{d:`M${p.x},${p.y} v-59`,stroke:'#b89b71','stroke-width':6},g);node('polygon',{points:points(corners(1.6,1.4,2,1)),fill:'#dbc17e','data-cow-rest':''},g);if(snapshot.expanded){const extra=node('g',{'data-cow-expansion':'','pointer-events':'none'},g);node('polygon',{points:points(corners(1.9,4.7,1.6,1.6)),fill:'#d6c88a',stroke:'#93a577','stroke-width':3},extra);for(const p of corners(1.9,4.7,1.6,.1))node('path',{d:`M${p.x},${p.y} v-34`,stroke:'#b89b71','stroke-width':4},extra);}if(snapshot.shade){const shade=node('g',{'data-cow-shade':'','pointer-events':'none'},g),fabric=corners(1.1,2.7,3,1.1);for(const p of [fabric[2],fabric[3]])node('path',{d:`M${p.x},${p.y} v-58`,stroke:'#8e9d77','stroke-width':4},shade);node('polygon',{points:points(fabric.map(p=>up(p,58))),fill:'#91b09a',stroke:'#5e846d','stroke-width':2},shade);}for(let i=0;i<8;i++){const p=iso(1.7+i%4*.5,1.7+Math.floor(i/4)*.5);node('path',{d:`M${p.x-8},${p.y} l13,-3 m-6,7 l10,-3`,stroke:'#bba464','stroke-width':2},g);}}
/** @param {Element} parent @param {ReturnType<typeof import('./cow-scene-snapshot.js').cowSnapshot>} snapshot */
function stations(parent,snapshot){
 for(const [id,x,y,key]of /** @type {const} */([['feed',1.4,4.8,'cowFeeder'],['water',5.8,2.5,'cowWaterTrough']])){const p=iso(x,y),g=node('g',{'data-cow-station':id,'data-cow-object':id,'aria-label':t(key)},parent),water=id==='water';if(water){g.setAttribute('data-cow-water-capacity',String(snapshot.waterCapacityMl));if(snapshot.waterCapacityMl>100000){node('path',{d:`M${p.x+27},${p.y-4} l28,-14 l12,17 l-28,14 Z`,fill:'#b0c9b6',stroke:'#6c9188','stroke-width':2,'data-cow-trough-extension':''},g);}}node('path',{d:`M${p.x-34},${p.y-12} v21 q34,17 68,0 v-21 Z`,fill:water?'#9db6ac':'#b59c73',stroke:water?'#6c9188':'#8e7c5b','stroke-width':2},g);node('ellipse',{cx:p.x,cy:p.y-12,rx:34,ry:12,fill:water?(snapshot.waterMl>0?'#78acb6':'#d3dfd5'):(snapshot.feedG>0?'#d3b772':'#c6ad74'),stroke:water?'#6c9188':'#8e7c5b','stroke-width':2},g);}
 const p=iso(5.8,5.8),stand=node('g',{'data-cow-station':'stand','data-cow-object':'stand','aria-label':t('cowMilkingStand')},parent);node('polygon',{points:points(corners(5.2,5.2,1.2,1.3).map(p=>up(p,7))),fill:'#d8bd88',stroke:'#aa8e62','stroke-width':2},stand);for(const dx of [-24,24])node('path',{d:`M${p.x+dx},${p.y+5} v-47 h${dx<0?15:-15}`,stroke:'#909e8a','stroke-width':4,fill:'none'},stand);
 const can=iso(6.2,4.1),milk=node('g',{'data-cow-station':'can','data-cow-object':'can','data-cow-stored-ml':snapshot.canMilkMl,'aria-label':t('cowMilkCan')},parent);node('path',{d:`M${can.x-14},${can.y-34} l-5,10 v27 q19,11 38,0 v-27 l-5,-10 Z`,fill:'#cbd6d0',stroke:'#81978d','stroke-width':2},milk);node('ellipse',{cx:can.x,cy:can.y-34,rx:14,ry:5,fill:'#e2e8dd',stroke:'#81978d','stroke-width':2},milk);node('path',{d:`M${can.x-14},${can.y-27} q-20,-1 -10,18 M${can.x+14},${can.y-27} q20,-1 10,18`,fill:'none',stroke:'#81978d','stroke-width':3},milk);
 if(snapshot.canMilkMl>0){const height=Math.max(1,Math.round(snapshot.canMilkMl/20000*24));node('rect',{x:can.x-10,y:can.y+2-height,width:20,height,rx:3,fill:'#fff7de','data-cow-can-fill':''},milk);}
 if(snapshot.cooler.owned){const p=iso(.9,6),tank=node('g',{'data-cow-cooler':'','data-cow-cooling':snapshot.cooler.status,'data-cow-cold-ml':snapshot.cooler.storedMl,'pointer-events':'none'},parent);node('path',{d:`M${p.x-22},${p.y-40} v38 q22,16 44,0 v-38 Z`,fill:'#a3bfc1',stroke:'#6c9188','stroke-width':2},tank);node('ellipse',{cx:p.x,cy:p.y-40,rx:22,ry:8,fill:'#d2e0d8',stroke:'#6c9188','stroke-width':2},tank);node('rect',{x:p.x-4,y:p.y-30,width:8,height:24,rx:3,fill:'#6f9698'},tank);if(snapshot.cooler.storedMl)node('rect',{x:p.x-3,y:p.y-7-22*snapshot.cooler.storedMl/40000,width:6,height:22*snapshot.cooler.storedMl/40000,fill:'#fff6dc','data-cow-cooler-fill':''},tank);node('circle',{cx:p.x+14,cy:p.y-25,r:3,fill:snapshot.cooler.status==='cooling'?'#437a5d':snapshot.cooler.status==='paused_no_funds'?'#bc8b43':'#82999a'},tank);}const sign=iso(5.6,.8),coop=node('g',{'data-cow-station':'coop','data-cow-object':'coop','aria-label':t('cowCoop')},parent);node('path',{d:`M${sign.x},${sign.y+6} v-57`,stroke:'#ad9164','stroke-width':5},coop);node('rect',{x:sign.x-36,y:sign.y-56,width:72,height:30,rx:5,fill:'#f2e5bd',stroke:'#bca16b','stroke-width':2},coop);node('text',{x:sign.x,y:sign.y-37,'font-size':11,'text-anchor':'middle',fill:'#36553c'},coop).textContent=t('cowCoopSign');
 const clean=iso(.8,3.3);if(snapshot.sanitation){const p=iso(.8,4),rack=node('g',{'data-cow-sanitation':'','pointer-events':'none'},parent);node('path',{d:`M${p.x-14},${p.y-15} l4,23 q12,6 24,0 l4,-23`,fill:'#bdced0',stroke:'#769491','stroke-width':2},rack);node('ellipse',{cx:p.x+4,cy:p.y-15,rx:16,ry:5,fill:'#e5e6d3',stroke:'#769491'},rack);node('path',{d:`M${p.x-7},${p.y-17} v-18 h21 v18`,fill:'none',stroke:'#769491','stroke-width':3},rack);}const brush=node('g',{'data-cow-station':'clean','data-cow-object':'clean','aria-label':t('cowCleanStation')},parent);node('path',{d:`M${clean.x},${clean.y} l20,-34`,stroke:'#b08c5c','stroke-width':4},brush);node('path',{d:`M${clean.x-13},${clean.y-8} l23,10 l-7,12 l-23,-10 Z`,fill:'#dbbc74',stroke:'#b49a66','stroke-width':2},brush);
}
/** Original SVG presentation: no resources, timers, grants or persistence. @param {ReturnType<typeof import('./cow-scene-snapshot.js').cowSnapshot>} snapshot */
export function renderCowWorld(snapshot){const host=/** @type {HTMLElement} */(document.querySelector('#world'));host.replaceChildren();const svg=node('svg',{viewBox:'0 0 900 540',class:'farm-scene cow-scene',role:'img','aria-label':t('cowArea')},host);node('title',{},svg).textContent=t('cowArea');node('ellipse',{cx:450,cy:355,rx:337,ry:137,fill:'#91a779',opacity:'.23'},svg);const map=node('g',{id:'map-camera'},svg);node('polygon',{points:'98,236 450,412 802,236 802,263 450,439 98,263',fill:'#92a975'},map);for(let y=0;y<8;y++)for(let x=0;x<8;x++){const p=iso(x,y);node('polygon',{points:diamond(p.x,p.y),fill:(x+y)%4===0?'#d8dfb6':'#cbd7a7',stroke:'#b8c792','stroke-width':'.5','data-cow-tile':y*8+x},map);}const edges=[[.3,.3,6.8,.3],[.3,.3,.3,6.8],[6.8,.3,6.8,6.8],[.3,6.8,6.8,6.8]];for(const edge of edges.slice(0,2))fence(map,edge);barn(map,snapshot);stations(map,snapshot);snapshot.herd.forEach((cow,index)=>drawCow(map,cow,index));node('text',{x:450,y:475,'text-anchor':'middle','font-size':15,fill:'#415d40','data-cow-owned':snapshot.herd.length},svg).textContent=t('cowCount')+': '+snapshot.herd.length+' / '+snapshot.capacity;for(const edge of edges.slice(2))fence(map,edge);const short=/** @type {Record<string,string>} */({barn:'cowShortBarn',feed:'cowShortFeed',water:'cowShortWater',stand:'cowShortStand',can:'cowMilkCan',coop:'cowCoopSign',clean:'cowShortClean'});host.querySelectorAll('[data-cow-object]').forEach(object=>{const id=object.getAttribute('data-cow-object')||'';object.setAttribute('data-cow-short-label',short[id]?t(short[id]):t('cowName')+' '+(id==='cow.starter.a'?'A':id==='cow.starter.b'?'B':'C'));});bindCamera(host,{area:'cow',redraw:()=>renderCowWorld(snapshot)});}

/** @param {Element} parent @param {ReturnType<typeof import('./cow-scene-snapshot.js').cowSnapshot>['herd'][number]} cow @param {number} index */
function drawCow(parent,cow,index){const spots=[[2.9,3.3],[4.4,4.6],[2.6,5.8]],p=iso(.../** @type {[number,number]} */(spots[index])),ordinal=cow.id==='cow.starter.a'?0:cow.id==='cow.starter.b'?1:2,g=node('g',{transform:`translate(${p.x} ${p.y})`,'data-cow':cow.id,'data-cow-object':cow.id,'data-cow-coat':ordinal,'data-cow-activity':cow.activity,'data-cow-ready-ml':cow.milkReadyMl,'data-cow-milking-ready':String(cow.canMilk),'data-cow-lactating':String(cow.lactating),'aria-label':t('cowName')+' '+String.fromCharCode(65+ordinal)+' · '+t(cow.lactating?'cowLactating':'cowDry')+(cow.milkReadyMl?' · '+t('cowMilkReady')+' '+cow.milkReadyMl/1000+' L':''),role:'img'},parent);node('title',{},g).textContent=g.getAttribute('aria-label');node('ellipse',{cx:0,cy:7,rx:40,ry:12,fill:'#71885a',opacity:'.28'},g);const motion=node('g',{class:'cow-motion','data-activity':cow.activity},g),figure=node('g',{class:'cow-figure'},motion),coat=ordinal===1?'#a67f5e':'#4f5348';for(const x of [-25,-12,16,28]){node('path',{d:`M${x},-10 l-2,22 h7 l2,-24`,fill:'#e9dfbd',stroke:'#b8b28f','stroke-width':1},figure);node('path',{d:`M${x-2},11 h8`,stroke:'#535445','stroke-width':4},figure);}node('path',{d:'M-31,-24 q-12,-10 -11,9 l-3,14',fill:'none',stroke:'#b3a98d','stroke-width':3},figure);node('ellipse',{cx:-2,cy:-20,rx:36,ry:22,fill:'#f6eed6',stroke:'#bdb494','stroke-width':1.2},figure);node('path',{d:ordinal===1?'M-25,-34 q22,-10 25,5 q-3,22 -17,12 Z':'M-28,-33 q16,-12 22,1 l-7,19 l-18,-3 Z',fill:coat},figure);node('path',{d:'M11,-37 q15,-10 17,5 l-1,23 l-13,5 l-9,-10 Z',fill:coat},figure);node('path',{d:'M25,-38 q7,-17 18,-8 l10,20 l-5,15 l-17,-1 Z',fill:'#f4ead0',stroke:'#bdb494','stroke-width':1.2},figure);node('path',{d:'M29,-41 l-15,-8 l2,9 l12,5 M43,-43 l14,-7 l-2,9 l-8,5',fill:coat,stroke:'#b1a784','stroke-width':1},figure);node('ellipse',{cx:45,cy:-17,rx:13,ry:9,fill:'#d7b3a1',stroke:'#b79f8a'},figure);node('circle',{cx:39,cy:-32,r:2.2,fill:'#263e31'},figure);node('circle',{cx:48,cy:-19,r:1.4,fill:'#947d70'},figure);node('path',{d:'M29,-41 l2,-7 M43,-44 l-1,-7',stroke:'#d8cbaa','stroke-width':3,'stroke-linecap':'round'},figure);if(cow.canMilk){node('circle',{cx:0,cy:-61,r:10,fill:'#487961'},g);node('path',{d:'M0,-67 q-11,12 0,12 q11,0 0,-12',fill:'#fff9e7'},g);}}
